  for (i: 1 .. s.textLen()) {
    local ch = s.segment(i,1)
    local isUpper = ch === ch.uppercase() && !(ch ? number) && ch !== ch.lowercase()
    if (isUpper && i > 1) {
      result.add(current)
      current = ch
    } else {
      current = current _ ch
    }
  }
  if (!(current ? emptyText)) result.add(current)
  result
}
