func knapsack(weights, values, capacity) = {
  local n = weights.listLen()
  local dp = []
  for (i: 0 .. n) {
    local row = []
    for (j: 0 .. capacity) row.add(0)
    dp.add(row)
  }
  for (i: 1 .. n) {
    for (j: 0 .. capacity) {
      dp[i+1][j+1] = dp[i][j+1]
      if (weights[i] <= j) {
