  local carry = 0
  for (i: 1 .. 4) {
    local bit_a = floor(a / (2^(i-1))) % 2
    local bit_b = floor(b / (2^(i-1))) % 2
    local s = bit_a ~ bit_b ~ carry
    carry = (bit_a & bit_b) | (bit_a & carry) | (bit_b & carry)
    sum = sum + s * (2^(i-1))
  }
  sum
}
