func largestRectHistogram(heights) = {
  local n = heights.listLen()
  local stack = []
  local maxArea = 0
  for (i: 1 .. n+1) {
    local h = if (i <= n) heights[i] else 0
    while (!(stack ? emptyList) && heights[stack[stack.listLen()]] > h) {
      local height = heights[stack[stack.listLen()]]; stack.remove(stack.listLen())
      local width = if (stack ? emptyList) i-1 else i - stack[stack.listLen()] - 1
