func regularExpMatch(s, p) = {
  local m = s.textLen(); local n = p.textLen()
  local dp = []
  for (i: 0 .. m) {
    local row = []
    for (j: 0 .. n) row.add(false)
    dp.add(row)
  }
  dp[1][1] = true
  for (j: 2 .. n+1) {
    if (p.segment(j-1,1) === "*") dp[1][j] = dp[1][j-2]
  }
  for (i: 1 .. m) {
    for (j: 1 .. n) {
      local sc = s.segment(i,1); local pc = p.segment(j,1)
      if (pc === "*") {
        dp[i+1][j+1] = dp[i+1][j-1]
        if (p.segment(j-1,1) === "." || p.segment(j-1,1) === sc) {
          dp[i+1][j+1] = dp[i+1][j+1] || dp[i][j+1]
        }
      } else if (pc === "." || pc === sc) {
        dp[i+1][j+1] = dp[i][j]
      }
    }
  }
  dp[m+1][n+1]
}
