func buildHeap(lst) = {
  local arr = copyList(lst)
  local n = arr.listLen()
  func siftDown491(i, size) = {
    local done = false
    while (!done) {
      local largest = i
      if (2*i <= size && arr[2*i] > arr[largest]) largest = 2*i
      if (2*i+1 <= size && arr[2*i+1] > arr[largest]) largest = 2*i+1
      if (largest != i) {
        local t = arr[i]; arr[i] = arr[largest]; arr[largest] = t
        i = largest
      } else {
        done = true
      }
    }
  }
  for (i: floor(n/2) .. 1 step -1) {
    siftDown491(i, n)
  }
  arr
}

